import { describe, it, expect } from "vitest";
import { readFile } from "node:fs/promises";
import { readFileSync } from "node:fs";
import {
  buildToolsContract,
  namesSha256,
  TOOLS_CONTRACT_PATH,
  type ToolsContract,
} from "../scripts/tools-contract.js";

// Gateway contract baseline, the one source for this test and the CI and
// release smoke (`--baseline tests/gateway-baseline.json`). It is not
// regenerated by `npm run refresh-snapshot`: changing it is a deliberate
// contract change. 201 tools before the spec refresh of 2026-10; 202 since that
// refresh (B-017) added hcloud_get_network_members, no tool was removed.
const baseline = JSON.parse(
  readFileSync(new URL("./gateway-baseline.json", import.meta.url), "utf8"),
) as { toolCount: number; namesSha256: string };
const BASELINE_TOOL_COUNT = baseline.toolCount;
const BASELINE_NAMES_SHA256 = baseline.namesSha256;

describe("tools contract (registry as built by src/index.ts)", () => {
  const current = buildToolsContract();

  it("keeps the baseline tool count and tool names", () => {
    expect(current.toolCount).toBe(BASELINE_TOOL_COUNT);
    expect(namesSha256(current.tools.map((t) => t.name))).toBe(BASELINE_NAMES_SHA256);
    expect(current.namesSha256).toBe(BASELINE_NAMES_SHA256);
  });

  it("matches the committed snapshot for every tool (required, schema, description, annotations)", async () => {
    const committed: ToolsContract = JSON.parse(await readFile(TOOLS_CONTRACT_PATH, "utf8"));
    expect(committed.toolCount).toBe(BASELINE_TOOL_COUNT);
    expect(committed.namesSha256).toBe(BASELINE_NAMES_SHA256);
    expect(current).toEqual(committed);
  });
});
